import SwiftUI

/// Mard 通用色号色板（295 色，与 PIXDOU 官方色板一致，含可可/漫漫/盼盼/米小窝对照色号）
struct BeadColor: Identifiable, Hashable {
    let id: Int            // 官方 colorId
    let mard: String        // Mard 色号
    let coco: String        // 可可色号
    let manman: String      // 漫漫色号
    let panpan: String      // 盼盼色号
    let mixiaowo: String    // 米小窝色号
    let r: UInt8
    let g: UInt8
    let b: UInt8

    var color: Color { Color(red: Double(r)/255, green: Double(g)/255, blue: Double(b)/255) }
    var uiColor: UIColor { UIColor(red: CGFloat(r)/255, green: CGFloat(g)/255, blue: CGFloat(b)/255, alpha: 1) }
}

