    static let groups: [(letter: String, colors: [BeadColor])] = {
        var dict: [String: [BeadColor]] = [:]
        for c in all { dict[String(c.mard.prefix(1)), default: []].append(c) }
        return dict.sorted { $0.key < $1.key }.map { (letter: $0.key, colors: $0.value) }
    }()

    static let byId: [Int: BeadColor] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

